-- 1) Index Only Scan を狙うため、必要列を含む複合インデックスを作成
CREATE INDEX IF NOT EXISTS idx_orders_status_amount ON orders(status, amount);

-- 2) 可視性マップ更新を期待して VACUUM (ANALYZE)
VACUUM (ANALYZE) orders;

-- 3) 統計情報を更新して、推定がどう変わるか再確認
ANALYZE orders;

EXPLAIN
SELECT *
FROM orders
WHERE status = 'paid';
